import sys, zipfile, base64, struct, io, re
def parse(path):
    z = zipfile.ZipFile(path)
    for n in z.namelist():
        if n.startswith('customXml/item') and not 'Props' in n:
            raw = z.read(n)
            txt = raw.decode('utf-16') if raw[:2] in (b'\xff\xfe', b'\xfe\xff') else raw.decode('utf-8','ignore')
            m = re.search(r'<DataMashup[^>]*>(.*?)</DataMashup>', txt, re.S)
            if m: return base64.b64decode(m.group(1).strip())
def split(b):
    v, = struct.unpack_from('<I', b, 0); o = 4
    ln, = struct.unpack_from('<I', b, o); o += 4; pkg = b[o:o+ln]; o += ln
    ln, = struct.unpack_from('<I', b, o); o += 4; perm = b[o:o+ln]; o += ln
    return pkg, perm
for p in sys.argv[1:]:
    pkg, perm = split(parse(p))
    print('=====', p); print('PERMISSIONS:', perm.decode('utf-8','ignore'))
    m = zipfile.ZipFile(io.BytesIO(pkg)).read('Formulas/Section1.m').decode('utf-8','ignore')
    open(p.split('\')[-1].split('/')[-1] + '.m', 'w', encoding='utf-8').write(m)
    print('queries:', re.findall(r'shared\s+(#?"[^"]+"|\w+)\s*=', m))
